import json, os, pathlib, re, runpy, subprocess, tomllib
home = pathlib.Path.home()
codex_home = pathlib.Path(os.environ.get("CODEX_HOME") or home / ".codex")
names = []
settings = codex_home / "config.toml"
if settings.is_file():
    with settings.open("rb") as stream:
        config = tomllib.load(stream)
    for key, value in config.get("plugins", {}).items():
        if key.startswith("task-router@") and isinstance(value, dict) and value.get("enabled", True):
            names.append(key.split("@", 1)[1])
if not names:
    personal = home / ".agents/plugins/marketplace.json"
    if personal.is_file():
        name = json.loads(personal.read_text()).get("name")
        if isinstance(name, str):
            names.append(name)
    names.append("fengbochao-plugins")
if os.environ.get("TASK_ROUTER_MARKETPLACE"):
    names = [os.environ["TASK_ROUTER_MARKETPLACE"]]
plugins = {}
for name in dict.fromkeys(names):
    if not re.fullmatch(r"[A-Za-z0-9_-]+", name):
        raise RuntimeError("Invalid Task Router marketplace name.")
    result = subprocess.run(["codex", "plugin", "list", "--marketplace", name, "--json"], stdin=subprocess.DEVNULL, capture_output=True, text=True, timeout=15)
    if result.returncode:
        continue
    for plugin in json.loads(result.stdout).get("installed", []):
        if plugin.get("name") == "task-router" and plugin.get("enabled", True):
            plugins[(plugin.get("marketplaceName"), plugin.get("version"))] = plugin
if len(plugins) != 1:
    raise RuntimeError("Task Router needs one enabled installation; check the Codex plugin panel.")
plugin = next(iter(plugins.values()))
parts = [plugin.get("marketplaceName"), plugin.get("name"), plugin.get("version")]
if any(not isinstance(p, str) or not re.fullmatch(r"[A-Za-z0-9_.+-]+", p) or p in (".", "..") for p in parts):
    raise RuntimeError("Invalid Task Router installation metadata.")
cache = codex_home / "plugins/cache"
entry = cache.joinpath(*parts, "scripts", "bootstrap_mcp.py")
if not entry.is_file() or not entry.resolve().is_relative_to(cache.resolve()):
    raise RuntimeError("Task Router runtime is missing from the installed plugin; reinstall it in Codex.")
runpy.run_path(str(entry), run_name="__main__")
